-- A confirmed billing transition preserves the cycle and moves its cash date.
-- Raw invoices, purchases, installment numbers and realized movements stay intact.
CREATE TABLE public.lts_card_due_transition_v370 (
 user_id uuid NOT NULL REFERENCES auth.users(id),family text NOT NULL,
 last_old_due date NOT NULL,first_new_due date NOT NULL,decision_source text NOT NULL,
 confirmed_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,family),
 CHECK(first_new_due>last_old_due AND first_new_due<=last_old_due+interval '3 months')
);
ALTER TABLE public.lts_card_due_transition_v370 ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.lts_card_due_transition_v370 FROM PUBLIC,anon,authenticated;
CREATE POLICY owner_read ON public.lts_card_due_transition_v370 FOR SELECT TO authenticated USING(user_id=(SELECT auth.uid()));
GRANT SELECT ON public.lts_card_due_transition_v370 TO authenticated;
GRANT ALL ON public.lts_card_due_transition_v370 TO service_role;
CREATE TRIGGER transition_changed_v370 AFTER INSERT OR UPDATE OR DELETE ON public.lts_card_due_transition_v370
 FOR EACH STATEMENT EXECUTE FUNCTION public.lts_card_due_rule_changed_v290();

CREATE FUNCTION public.lts_card_projection_date_v370(p_user_id uuid,p_family text,p_month date,p_fallback date,p_bank_anchor date DEFAULT NULL)
RETURNS date LANGUAGE sql STABLE SECURITY INVOKER SET search_path='' AS $$
WITH transition AS(SELECT t.* FROM public.lts_card_due_transition_v370 t
 WHERE t.user_id=p_user_id AND t.family=p_family AND p_month>date_trunc('month',t.last_old_due)::date),
target AS(SELECT p_month,
 CASE WHEN t.family IS NOT NULL AND(p_bank_anchor IS NULL OR p_bank_anchor<t.first_new_due)
 THEN (extract(year FROM t.first_new_due)::int*12+extract(month FROM t.first_new_due)::int)
 -(extract(year FROM t.last_old_due)::int*12+extract(month FROM t.last_old_due)::int)-1 ELSE 0 END month_shift,
 t.first_new_due FROM(SELECT 1)x LEFT JOIN transition t ON true),
dated AS(SELECT(date_trunc('month',p_month)+make_interval(months=>month_shift))::date target_month,first_new_due FROM target)
SELECT CASE WHEN r.due_day IS NULL AND d.first_new_due IS NULL THEN p_fallback
 ELSE d.target_month+least(coalesce(r.due_day,extract(day FROM d.first_new_due)::int),
 extract(day FROM d.target_month+interval '1 month -1 day')::int)-1 END
FROM dated d LEFT JOIN LATERAL(SELECT due_day FROM public.lts_card_due_rule_v290 r
 WHERE r.user_id=p_user_id AND r.family=p_family AND r.effective_from<=d.target_month
 ORDER BY effective_from DESC LIMIT 1)r ON true
$$;
REVOKE ALL ON FUNCTION public.lts_card_projection_date_v370(uuid,text,date,date,date) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.lts_card_projection_date_v370(uuid,text,date,date,date) TO service_role;

CREATE FUNCTION public.lts_card_transition_cash_date_v370(p_user_id uuid,p_family text,p_date date)
RETURNS date LANGUAGE sql STABLE SECURITY INVOKER SET search_path='' AS $$
SELECT coalesce((SELECT first_new_due FROM public.lts_card_due_transition_v370 t
 WHERE t.user_id=p_user_id AND t.family=p_family AND p_date>t.last_old_due AND p_date<t.first_new_due),p_date)
$$;
REVOKE ALL ON FUNCTION public.lts_card_transition_cash_date_v370(uuid,text,date) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.lts_card_transition_cash_date_v370(uuid,text,date) TO service_role;

CREATE FUNCTION public.lts_card_transition_overlay_v370(p_user_id uuid,p_payload jsonb)
RETURNS jsonb LANGUAGE sql STABLE SECURITY INVOKER SET search_path='' AS $$
SELECT CASE WHEN jsonb_typeof(p_payload->'cards') IS DISTINCT FROM 'array' THEN p_payload ELSE
 jsonb_set(p_payload,'{cards}',coalesce((SELECT jsonb_agg(
 CASE WHEN t.family IS NULL THEN card ELSE card||jsonb_build_object('cycles',coalesce((
  WITH cycles AS MATERIALIZED(SELECT c,ord,
   (c->>'invoice_source_id' IS NOT NULL OR c->>'basis'='open_finance_invoice_v263') official
   FROM jsonb_array_elements(coalesce(card->'cycles','[]'))WITH ORDINALITY a(c,ord)),
  anchor AS(SELECT max((c->>'due_date')::date)due_date FROM cycles WHERE official),
  dates AS(SELECT c,ord,official,CASE
   WHEN(c->>'month')::date<=date_trunc('month',t.last_old_due)::date OR c->>'payment_status'='paid' THEN(c->>'due_date')::date
   WHEN official THEN public.lts_card_transition_cash_date_v370(p_user_id,t.family,(c->>'due_date')::date)
   ELSE public.lts_card_projection_date_v370(p_user_id,t.family,(c->>'month')::date,(c->>'due_date')::date,
    CASE WHEN c->>'basis' IN('open_finance_composition','received_and_projected_installments','derived_current_installments') THEN anchor.due_date END)END due_date
   FROM cycles CROSS JOIN anchor)
  SELECT jsonb_agg(c||CASE WHEN due_date IS DISTINCT FROM(c->>'due_date')::date THEN
   jsonb_build_object('due_date',due_date,'original_due_date',coalesce(c->>'original_due_date',c->>'due_date'),
   'due_date_basis','owner_confirmed_cycle_transition','transition_first_due_date',t.first_new_due)
   ELSE '{}'::jsonb END ORDER BY ord) FROM dates d
  WHERE d.official OR NOT EXISTS(SELECT 1 FROM dates actual WHERE actual.official AND actual.due_date=d.due_date
   AND d.due_date>=t.first_new_due AND(d.c->>'month')::date>date_trunc('month',t.last_old_due)::date)
 ),'[]'::jsonb))END ORDER BY n)
 FROM jsonb_array_elements(p_payload->'cards')WITH ORDINALITY a(card,n)
 LEFT JOIN public.lts_card_due_transition_v370 t ON t.user_id=p_user_id AND t.family=card->>'family'),'[]'::jsonb),false)END
$$;
REVOKE ALL ON FUNCTION public.lts_card_transition_overlay_v370(uuid,jsonb) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.lts_card_transition_overlay_v370(uuid,jsonb) TO service_role;

-- Leased edits below retain existing security attributes and source priorities.

DO $patch$
DECLARE target regprocedure;definition text;attributes jsonb;item jsonb;
BEGIN
 FOR item IN SELECT value FROM jsonb_array_elements($leases$[{"name": "lts_aeternum_forecast_cycles_v311", "md5": "89e5fbcd2a27327d9315794f7ecdb7e5", "new_definition": "CREATE OR REPLACE FUNCTION public.lts_aeternum_forecast_cycles_v311(p_user_id uuid)\n RETURNS TABLE(reference_month date, due_date date, amount numeric, item_count bigint, received_amount numeric, projected_amount numeric, observed_at timestamp with time zone, unclassified bigint, items jsonb, basis text)\n LANGUAGE sql\n STABLE\n SET search_path TO ''\n SET \"TimeZone\" TO 'America/Sao_Paulo'\nAS $function$\nWITH source_rows AS MATERIALIZED (\n SELECT r.*,s.institution_code,s.provider_account_ref,\n CASE WHEN r.total_installments BETWEEN 2 AND 120 AND r.installment_number BETWEEN 1 AND r.total_installments\n AND nullif(s.raw_payload#>>'{creditCardMetadata,purchaseDate}','') IS NOT NULL\n AND r.purchase_date IS NOT NULL AND nullif(r.last4,'') IS NOT NULL\n AND nullif(s.provider_account_ref,'') IS NOT NULL\n THEN jsonb_build_array(r.family,s.institution_code,s.provider_account_ref,r.last4,r.purchase_date,\n public.lts_card_merchant_key_v226(r.description),r.total_installments,\n extract(year FROM r.reference_month)::int*12+extract(month FROM r.reference_month)::int-r.installment_number)::text END plan_key\n FROM public.lts_card_source_rows_v226(p_user_id) r\n JOIN public.lts_open_finance_staging s ON s.id=r.source_id AND s.user_id=p_user_id\n AND s.resource_type='card_transaction' AND s.provider_deleted_at IS NULL AND s.currency='BRL'\n WHERE r.family='aeternum' AND NOT r.is_payment\n), bills AS MATERIALIZED (\n SELECT b.*,s.institution_code,s.provider_account_ref,s.normalized_payload->>'provider_id' bill_id\n FROM public.lts_current_received_card_bills_v263(p_user_id) b\n JOIN public.lts_open_finance_staging s ON s.id=b.invoice_source_id AND s.user_id=p_user_id\n WHERE b.family='aeternum' AND s.provider_deleted_at IS NULL AND s.currency='BRL'\n), latest AS MATERIALIZED (\n SELECT DISTINCT ON(family,institution_code,provider_account_ref) * FROM bills\n ORDER BY family,institution_code,provider_account_ref,reference_month DESC,due_date DESC\n), anchor AS MATERIALIZED (\n SELECT r.* FROM source_rows r JOIN latest b USING(family,institution_code,provider_account_ref)\n WHERE r.bill_id=b.bill_id AND r.reference_month=b.reference_month AND r.provider_status='POSTED'\n), observed AS MATERIALIZED (\n SELECT r.* FROM source_rows r LEFT JOIN latest b USING(family,institution_code,provider_account_ref)\n WHERE r.provider_status='PENDING' AND r.reference_month>=date_trunc('month',current_date)::date\n AND (b.reference_month IS NULL OR r.reference_month>b.reference_month)\n AND NOT EXISTS(SELECT 1 FROM bills x WHERE x.family=r.family AND x.reference_month=r.reference_month\n AND x.institution_code=r.institution_code AND x.provider_account_ref=r.provider_account_ref)\n), plan_inputs AS MATERIALIZED (\n SELECT * FROM anchor WHERE plan_key IS NOT NULL AND amount>0\n UNION ALL SELECT * FROM observed WHERE plan_key IS NOT NULL AND amount>0\n), groups AS MATERIALIZED (\n SELECT family,plan_key,reference_month,installment_number,total_installments,count(*) n,sum(amount) amount,\n jsonb_agg(to_jsonb(r)-ARRAY['plan_key','institution_code','provider_account_ref'] ORDER BY source_id) items\n FROM plan_inputs r GROUP BY family,plan_key,reference_month,installment_number,total_installments\n), projected AS MATERIALIZED (\n SELECT DISTINCT ON(g.plan_key,(g.reference_month+make_interval(months=>step))::date)\n g.*,step,(g.reference_month+make_interval(months=>step))::date target_month\n FROM groups g CROSS JOIN LATERAL generate_series(1,g.total_installments-g.installment_number) step\n WHERE (g.reference_month+make_interval(months=>step))::date>=date_trunc('month',current_date)::date\n AND NOT EXISTS(SELECT 1 FROM groups actual WHERE actual.plan_key=g.plan_key\n AND actual.reference_month=(g.reference_month+make_interval(months=>step))::date)\n ORDER BY g.plan_key,(g.reference_month+make_interval(months=>step))::date,g.reference_month DESC\n), items AS MATERIALIZED (\n SELECT family,reference_month,amount,'received'::text kind,to_jsonb(r)-ARRAY['plan_key','institution_code','provider_account_ref'] item\n FROM observed r\n UNION ALL\n SELECT family,target_month,(i->>'amount')::numeric,'projected',i||jsonb_build_object('reference_month',target_month,\n 'due_date',NULL,'installment_number',(i->>'installment_number')::int+step,'provider_status','PROJECTED',\n 'projection_basis','remaining_installments_from_latest_received_cycle','projection_source_month',reference_month)\n FROM projected CROSS JOIN LATERAL jsonb_array_elements(items)i\n WHERE NOT EXISTS(SELECT 1 FROM bills b WHERE b.family=projected.family AND b.reference_month=projected.target_month)\n)\n, cycle_rows AS (\nSELECT family,reference_month,round(sum(amount),2) amount,\n count(*) item_count,count(*)filter(where kind='received') received_count,count(*)filter(where kind='projected') projected_count,\n round(coalesce(sum(amount)filter(where kind='received'),0),2) received_amount,\n round(coalesce(sum(amount)filter(where kind='projected'),0),2) projected_amount,\n max((item->>'observed_at')::timestamptz) observed_at,\n count(*)filter(where item->>'category_basis'='unresolved') unclassified,\n jsonb_agg(item ORDER BY item->>'description',item->>'source_id') items\nFROM items GROUP BY family,reference_month\n)\nSELECT c.reference_month,\n public.lts_card_projection_date_v370(p_user_id,'aeternum',c.reference_month,\n c.reference_month+least(coalesce(rule.due_day,extract(day FROM latest.due_date)::int),\n extract(day FROM(c.reference_month+interval '1 month -1 day'))::int)-1,latest.due_date),\n c.amount,c.item_count,c.received_amount,c.projected_amount,c.observed_at,c.unclassified,c.items,\n CASE WHEN c.received_count>0 AND c.projected_count>0 THEN 'received_and_projected_installments'\n WHEN c.received_count>0 THEN 'open_finance_composition' ELSE 'derived_current_installments' END\nFROM cycle_rows c CROSS JOIN latest\nLEFT JOIN LATERAL(SELECT r.due_day FROM public.lts_card_due_rule_v290 r\n WHERE r.user_id=p_user_id AND r.family='aeternum' AND r.effective_from<=c.reference_month\n ORDER BY r.effective_from DESC LIMIT 1)rule ON true\nWHERE c.reference_month>latest.reference_month AND c.amount>=0\nAND (SELECT count(*) FROM latest WHERE family='aeternum')=1\nAND abs(latest.amount-coalesce((SELECT sum(r.amount) FROM anchor r),0))<0.005\nAND NOT EXISTS(SELECT 1 FROM anchor r WHERE r.total_installments>r.installment_number\n AND r.installment_number>0 AND r.plan_key IS NULL)\nAND NOT EXISTS(SELECT 1 FROM observed r WHERE r.total_installments>r.installment_number\n AND r.installment_number>0 AND r.plan_key IS NULL)\nORDER BY c.reference_month\n$function$\n"}, {"name": "lts_card_due_overlay_v290", "md5": "d553851639c26ac15c9d310454e9177d", "new_definition": "CREATE OR REPLACE FUNCTION public.lts_card_due_overlay_v290(p_user_id uuid, p_payload jsonb)\n RETURNS jsonb\n LANGUAGE sql\n STABLE\n SET search_path TO ''\nAS $function$\nSELECT public.lts_card_transition_overlay_v370(p_user_id,CASE WHEN jsonb_typeof(p_payload->'cards')='array' THEN jsonb_set(p_payload,'{cards}',coalesce((\n SELECT jsonb_agg(c.value||jsonb_build_object('cycles',coalesce((\n SELECT jsonb_agg(y.value||CASE WHEN r.due_day IS NOT NULL AND y.value->>'invoice_source_id' IS NULL THEN\n jsonb_build_object('due_date',((y.value->>'month')::date+r.due_day-1),\n 'original_due_date',y.value->>'due_date','due_date_basis','owner_confirmed_cycle_rule',\n 'due_rule_effective_from',r.effective_from,'due_rule_confirmed_at',r.confirmed_at)\n WHEN r.due_day IS NOT NULL AND (y.value->>'due_date')::date<>((y.value->>'month')::date+r.due_day-1)\n THEN jsonb_build_object('due_date_conflict',true,'owner_expected_due_date',((y.value->>'month')::date+r.due_day-1))\n ELSE '{}'::jsonb END ORDER BY y.ord)\n FROM jsonb_array_elements(coalesce(c.value->'cycles','[]')) WITH ORDINALITY y(value,ord)\n LEFT JOIN LATERAL(SELECT r.* FROM public.lts_card_due_rule_v290 r WHERE r.user_id=p_user_id\n AND r.family=c.value->>'family' AND (y.value->>'month')::date>=r.effective_from\n ORDER BY r.effective_from DESC LIMIT 1)r ON true\n ),'[]'::jsonb)) ORDER BY c.ord)\n FROM jsonb_array_elements(p_payload->'cards') WITH ORDINALITY c(value,ord)\n),'[]'),false) ELSE p_payload END)\n$function$\n"}, {"name": "lts_card_projection_rows_v290", "md5": "0d7b3bc53bdb19336de251596d321043", "new_definition": "CREATE OR REPLACE FUNCTION public.lts_card_projection_rows_v290(p_user_id uuid)\n RETURNS TABLE(user_id uuid, card_name text, reference_month date, due_date date, status text, amount numeric, source text)\n LANGUAGE sql\n SET search_path TO ''\n SET \"TimeZone\" TO 'America/Sao_Paulo'\nAS $function$\nWITH forecast AS MATERIALIZED(SELECT * FROM public.lts_aeternum_forecast_cycles_v311(p_user_id)),\nenabled AS MATERIALIZED(SELECT DISTINCT ON(family) family,effective_from,due_day\n FROM public.lts_card_due_rule_v290 WHERE user_id=p_user_id ORDER BY family,effective_from DESC),\nrows AS MATERIALIZED(SELECT r.* FROM public.lts_card_source_rows_v226(p_user_id)r\n WHERE r.provider_status IN('PENDING','DOCUMENTED') AND NOT r.is_payment),\nbills AS MATERIALIZED(SELECT * FROM public.lts_current_received_card_bills_v263(p_user_id)),\ngrouped AS(SELECT r.family,r.reference_month,round(sum(r.amount),2) amount,rule.due_day\n FROM rows r JOIN enabled rule ON rule.family=r.family AND r.reference_month>=rule.effective_from\n WHERE r.family<>'c6' AND NOT(r.family='aeternum' AND EXISTS(SELECT 1 FROM forecast f WHERE f.reference_month=r.reference_month)) AND r.reference_month>=date_trunc('month',current_date)::date\n AND NOT EXISTS(SELECT 1 FROM bills b WHERE b.family=r.family AND b.reference_month=r.reference_month)\n GROUP BY r.family,r.reference_month,rule.due_day)\nSELECT p_user_id,ci.card_name,g.reference_month,public.lts_card_projection_date_v370(p_user_id,g.family,g.reference_month,g.reference_month+g.due_day-1,(SELECT max(b.due_date)FROM bills b WHERE b.family=g.family)),'projected'::text,g.amount,\n 'received_card_composition_v290'::text\nFROM grouped g JOIN LATERAL(SELECT i.card_name FROM public.card_invoices i\n WHERE i.user_id=p_user_id AND public.lts_card_family_v226(i.card_name,i.card_name)=g.family\n ORDER BY i.reference_month DESC,i.due_date DESC LIMIT 1)ci ON true\nWHERE g.amount>=0 AND public.lts_card_projection_date_v370(p_user_id,g.family,g.reference_month,g.reference_month+g.due_day-1,(SELECT max(b.due_date)FROM bills b WHERE b.family=g.family))>=current_date\nUNION ALL\nSELECT p_user_id,ci.card_name,f.reference_month,f.due_date,'projected'::text,f.amount,'received_card_composition_v290'::text\nFROM forecast f\nJOIN LATERAL(SELECT i.card_name FROM public.card_invoices i WHERE i.user_id=p_user_id\n AND public.lts_card_family_v226(i.card_name,i.card_name)='aeternum'\n ORDER BY i.reference_month DESC,i.due_date DESC LIMIT 1)ci ON true\n$function$\n"}, {"name": "lts_corrected_cashflow_fix86_v5", "md5": "52cf0dc7e916b166cc33d1f523571eed", "new_definition": "CREATE OR REPLACE FUNCTION public.lts_corrected_cashflow_fix86_v5(p_user_id uuid, p_from date, p_to date)\n RETURNS TABLE(event_date date, account text, description text, signed_amount numeric, source text, source_ref text, confidence text, account_assignment text, legacy_index integer, original_date date, displaced boolean)\n LANGUAGE sql\n SECURITY DEFINER\n SET search_path TO 'public'\n SET \"TimeZone\" TO 'America/Sao_Paulo'\nAS $function$\nwith scan as materialized (\n  select * from public.lts_corrected_cashflow_fix86_v4(p_user_id,p_from-31,p_to+31)\n), shifted as (\n  select\n    case when s.source='card_invoice' then public.lts_card_transition_cash_date_v370(p_user_id,public.lts_card_family_v226(coalesce(ci.card_name,s.description),coalesce(ci.card_name,s.description)),coalesce(nullif(ci.metadata->>'cash_effect_date','')::date,s.event_date))\n         when legacy_due.due_date is not null then legacy_due.due_date\n         else s.event_date end event_date,\n    s.account,s.description,s.signed_amount,s.source,s.source_ref,s.confidence,s.account_assignment,s.legacy_index,\n    s.original_date,\n    case when s.source='card_invoice' then public.lts_card_transition_cash_date_v370(p_user_id,public.lts_card_family_v226(coalesce(ci.card_name,s.description),coalesce(ci.card_name,s.description)),coalesce(nullif(ci.metadata->>'cash_effect_date','')::date,s.event_date))<>s.event_date\n         when legacy_due.due_date is not null then legacy_due.due_date<>s.event_date\n         else s.displaced end displaced\n  from scan s\n  left join public.card_invoices ci\n    on s.source='card_invoice'\n   and ci.user_id=p_user_id\n   and s.source_ref=ci.card_name||'|'||to_char(ci.reference_month,'YYYY-MM')\n  left join lateral (\n    select public.lts_card_projection_date_v370(p_user_id,'aeternum',date_trunc('month',s.event_date)::date,s.event_date,NULL) due_date\n    where s.source='legacy_fix86' and s.confidence='legacy_projection_adjusted'\n      and not coalesce(s.displaced,false) and s.signed_amount<0\n      and lower(trim(s.description))='visa aeternum' and s.account='Bradesco'\n  ) legacy_due on true\n)\nselect * from shifted where event_date between p_from and p_to\norder by event_date,source,description;\n$function$\n"}, {"name": "lts_card_invoice_amounts_v230", "md5": "9dc887ae44cb6968e877b2b048fccbcd", "new_definition": "CREATE OR REPLACE FUNCTION public.lts_card_invoice_amounts_v230(p_user_id uuid)\n RETURNS TABLE(user_id uuid, card_name text, reference_month date, due_date date, status text, amount numeric, source text)\n LANGUAGE plpgsql\n SET search_path TO ''\n SET \"TimeZone\" TO 'America/Sao_Paulo'\nAS $function$\n#variable_conflict use_column\nDECLARE memo jsonb; source_epoch bigint; fingerprint text;\nBEGIN\n IF p_user_id IS NULL THEN RETURN QUERY SELECT * FROM public.lts_card_invoice_amounts_v230_engine_v243(p_user_id); RETURN;END IF;\n SELECT epoch INTO source_epoch FROM public.lts_read_cache_epoch_v242 WHERE singleton=true;\n fingerprint:='source-v243:'||source_epoch;\n SELECT payload INTO memo FROM public.lts_v229_read_cache c WHERE c.user_id=p_user_id\n AND c.kind='lts_card_invoice_amounts_v230_v243' AND c.as_of=current_date AND c.from_date=current_date AND c.to_date=current_date\n AND c.source_fingerprint=fingerprint AND c.refreshed_at>clock_timestamp()-interval '5 minutes';\n IF memo IS NULL THEN\n  SELECT coalesce(jsonb_agg(to_jsonb(r)),'[]') INTO memo FROM public.lts_card_invoice_amounts_v230_engine_v243(p_user_id) r;\n  IF source_epoch IS DISTINCT FROM (SELECT epoch FROM public.lts_read_cache_epoch_v242 WHERE singleton=true) THEN\n   RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='source changed during read';\n  END IF;\n  IF NOT current_setting('transaction_read_only')::boolean THEN\n  IF NOT current_setting('transaction_read_only')::boolean THEN\n BEGIN\n INSERT INTO public.lts_v229_read_cache(user_id,kind,as_of,from_date,to_date,payload,source_fingerprint,refreshed_at)\n  VALUES(p_user_id,'lts_card_invoice_amounts_v230_v243',current_date,current_date,current_date,memo,fingerprint,clock_timestamp())\n  ON CONFLICT(user_id,kind,as_of,from_date,to_date) DO UPDATE SET payload=excluded.payload,source_fingerprint=excluded.source_fingerprint,refreshed_at=excluded.refreshed_at;\n EXCEPTION WHEN read_only_sql_transaction THEN NULL;\n END;\n END IF;\n  END IF;\n END IF;\n RETURN QUERY WITH current_projection AS MATERIALIZED(SELECT * FROM public.lts_card_projection_rows_v290(p_user_id)),\n base AS(SELECT r.*,a.ord FROM jsonb_array_elements(memo) WITH ORDINALITY a(j,ord)\n CROSS JOIN LATERAL jsonb_to_record(a.j) r(user_id uuid,card_name text,reference_month date,due_date date,status text,amount numeric,source text))\n SELECT b.user_id,b.card_name,b.reference_month,CASE WHEN b.status='projected' AND public.lts_card_family_v226(b.card_name,b.card_name)='aeternum' THEN public.lts_card_projection_date_v370(p_user_id,'aeternum',b.reference_month,b.due_date,NULL) ELSE public.lts_card_transition_cash_date_v370(p_user_id,public.lts_card_family_v226(b.card_name,b.card_name),b.due_date) END,CASE WHEN b.status IN('open','projected') AND public.lts_card_invoice_settled_v290(p_user_id,b.card_name,b.reference_month,b.due_date,b.amount) THEN 'paid' ELSE b.status END,b.amount,b.source FROM base b\n WHERE NOT(b.status='projected' AND public.lts_card_family_v226(b.card_name,b.card_name)='aeternum'\n AND EXISTS(SELECT 1 FROM public.lts_card_due_transition_v370 t WHERE t.user_id=p_user_id AND t.family='aeternum')\n AND EXISTS(SELECT 1 FROM public.lts_current_received_card_bills_v263(p_user_id) received WHERE received.family='aeternum'\n AND public.lts_card_transition_cash_date_v370(p_user_id,'aeternum',received.due_date)=public.lts_card_projection_date_v370(p_user_id,'aeternum',b.reference_month,b.due_date,NULL)))\n AND NOT EXISTS(SELECT 1 FROM current_projection p WHERE p.reference_month=b.reference_month\n AND public.lts_card_family_v226(p.card_name,p.card_name)=public.lts_card_family_v226(b.card_name,b.card_name))\n UNION ALL SELECT * FROM current_projection;\nEND $function$\n"}]$leases$::jsonb) LOOP
  SELECT p.oid::regprocedure INTO STRICT target FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public'AND p.proname=item->>'name';
  SELECT pg_get_functiondef(target),to_jsonb(p)-'prosrc' INTO definition,attributes FROM pg_proc p WHERE p.oid=target;
  IF md5(definition)<>item->>'md5' THEN RAISE EXCEPTION 'V370 source changed: %',item->>'name';END IF;
  EXECUTE item->>'new_definition';
  IF attributes IS DISTINCT FROM(SELECT to_jsonb(p)-'prosrc'FROM pg_proc p WHERE p.oid=target)THEN RAISE EXCEPTION 'V370 attributes changed: %',item->>'name';END IF;
 END LOOP;
END $patch$;
